// CloudtainerML rev0023: evidence provenance DAG / stale invalidation probe.
// Synthetic C++17 probe. Not a paper reproduction.
#include <algorithm>
#include <chrono>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <numeric>
#include <random>
#include <string>
#include <vector>
struct Ev{double relevance=0, source=0, revision=0, supports=0, contradicts=0, stale=0, contaminated=0, utility=0;};
struct Row{std::string regime,policy; int budget=0,n=0; double support=0, stale_miss=0, contam=0, cost=0, utility=0, cat=0;};
static std::string esc(const std::string&s){std::string o; for(char c:s){if(c=='"')o+="\\\""; else if(c=='\\')o+="\\\\"; else o+=c;} return o;}
static double clamp(double x,double a,double b){return std::max(a,std::min(b,x));}
static double rnd(std::mt19937_64&r,double a=0,double b=1){return std::uniform_real_distribution<double>(a,b)(r);} 
static std::vector<Ev> make_evidence(const std::string&reg,std::mt19937_64&rng,int m){std::vector<Ev> v; v.reserve(m+8); for(int i=0;i<m;i++){Ev e; e.relevance=rnd(rng,0.05,0.88); e.source=rnd(rng,0.35,0.98); e.revision=rnd(rng,0.25,1); e.supports=rnd(rng,0.05,0.75); e.contradicts=rnd(rng,0,0.35); e.stale=rnd(rng,0,0.45); e.contaminated=0; e.utility=e.supports*(0.7+0.3*e.source); if(i%9==0){e.supports+=0.25; e.utility+=0.15;} v.push_back(e);} int bad=(reg=="clean")?0:(reg=="stale_update"?4:reg=="contaminated_tool"?3:2); for(int j=0;j<bad;j++){Ev b; b.relevance=rnd(rng,0.58,0.98); b.source=(reg=="contaminated_tool"?rnd(rng,0.10,0.44):rnd(rng,0.30,0.75)); b.revision=(reg=="stale_update"?rnd(rng,0.0,0.25):rnd(rng,0.15,0.65)); b.supports=rnd(rng,0.25,0.70); b.contradicts=rnd(rng,0.45,0.95); b.stale=(reg=="stale_update"?rnd(rng,0.75,1.0):rnd(rng,0.30,0.80)); b.contaminated=(reg=="contaminated_tool"?rnd(rng,0.7,1.0):rnd(rng,0.35,0.8)); b.utility=rnd(rng,0.05,0.45); v.push_back(b);} if(reg=="conflict_resolution"){for(int j=0;j<4;j++){Ev c; c.relevance=rnd(rng,0.35,0.75); c.source=rnd(rng,0.70,1); c.revision=rnd(rng,0.76,1); c.supports=rnd(rng,0.50,0.92); c.contradicts=rnd(rng,0.0,0.2); c.stale=rnd(rng,0,0.15); c.contaminated=0; c.utility=rnd(rng,0.65,1.0); v.push_back(c);}} return v;}
static double score(const Ev&e,const std::string&pol){if(pol=="relevance_only") return e.relevance; if(pol=="source_weighted") return e.relevance+0.55*e.source; if(pol=="revision_aware") return e.relevance+0.45*e.source+0.58*e.revision-0.55*e.stale; if(pol=="provenance_dag") return e.relevance+0.52*e.source+0.62*e.revision+0.35*e.supports-0.70*e.contradicts-0.85*e.contaminated-0.42*e.stale; if(pol=="flowtrace_support") return 0.55*e.relevance+0.25*e.source+0.55*e.supports-0.65*e.contradicts-0.55*e.contaminated; if(pol=="oracle_evidence") return e.utility-8.0*e.contaminated-4.0*e.stale-2.0*e.contradicts; return e.relevance;}
static void add(Row&r,double s,double stale,double cont,double cost,double u,double cat){r.n++; r.support+=s; r.stale_miss+=stale; r.contam+=cont; r.cost+=cost; r.utility+=u; r.cat+=cat;}
int main(int argc,char**argv){std::string out="artifacts/probe-results/REV0023_EVIDENCE_PROVENANCE_DAG_SMOKE.json"; if(argc>1) out=argv[1]; auto t0=std::chrono::high_resolution_clock::now(); std::vector<std::string> regimes={"clean","stale_update","contaminated_tool","conflict_resolution","semantic_decoy"}; std::vector<std::string> policies={"relevance_only","source_weighted","revision_aware","provenance_dag","flowtrace_support","oracle_evidence"}; std::vector<int> budgets={4,8,16,32}; std::map<std::string,Row> rows; std::map<std::string,int>wins;
for(auto&reg:regimes) for(int budget:budgets) for(int seed=0; seed<100; ++seed){double best=-1e18; std::string bp; for(auto&pol:policies){std::mt19937_64 rng(320020+seed*103+budget*23+reg.size()*17+pol.size()*29); auto ev=make_evidence(reg,rng,52); std::vector<int> idx(ev.size()); std::iota(idx.begin(),idx.end(),0); std::stable_sort(idx.begin(),idx.end(),[&](int a,int b){return score(ev[a],pol)>score(ev[b],pol);}); int k=std::min<int>(budget,idx.size()); double support=0, stale=0, cont=0, cost=0; for(int i=0;i<k;i++){auto&e=ev[idx[i]]; support+=e.supports*(1-e.contradicts)*(1-e.contaminated); stale=std::max(stale,e.stale*e.contradicts); cont=std::max(cont,e.contaminated*e.relevance); cost+=(pol=="oracle_evidence"?2.0:pol=="provenance_dag"?1.45:pol=="flowtrace_support"?1.25:1.0);} support=clamp(support/(0.52*k),0,1.4); double cat=(stale>0.52 || cont>0.50)?1.0:0.0; double util=2.4*support-2.1*stale-2.5*cont-0.012*cost-0.8*cat; std::string key=reg+"|"+std::to_string(budget)+"|"+pol; if(!rows.count(key)){rows[key].regime=reg; rows[key].budget=budget; rows[key].policy=pol;} add(rows[key],support,stale,cont,cost,util,cat); if(util>best){best=util; bp=pol;}} wins[bp]++;}
 double seconds=std::chrono::duration<double>(std::chrono::high_resolution_clock::now()-t0).count(); std::ofstream f(out); f<<std::fixed<<std::setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0023\",\n  \"probe\": \"evidence_provenance_dag\",\n  \"language\": \"c++17\",\n  \"is_paper_reproduction\": false,\n  \"taxonomy\": [\"agent-memory\", \"provenance\", \"evidence-dag\", \"stale-invalidation\", \"native\"],\n"; f<<"  \"summary\": {\"row_count\": "<<rows.size()<<", \"seconds\": "<<seconds<<", \"primary_metric\": {\"name\": \"mean_utility\", \"direction\": \"higher_is_better\", \"winner_field\": \"winner_counts\"}, \"tail_metrics\": {\"has_catastrophic_proxy\": true, \"fields\": [\"catastrophic_evidence_failure_rate\", \"stale_invalidation_miss_rate\", \"contamination_read_rate\"]}, \"winner_counts\": {"; bool first=true; for(auto&kv:wins){if(!first)f<<", "; first=false; f<<"\""<<esc(kv.first)<<"\": "<<kv.second;} f<<"}, \"interpretation\": \"Treats memory entries as evidence-bearing objects with source/revision/use history, not bare semantic chunks.\"},\n  \"rows\": [\n"; int c=0; for(auto&kv:rows){auto&r=kv.second; double n=std::max(1,r.n); if(c++)f<<",\n"; f<<"    {\"regime\": \""<<esc(r.regime)<<"\", \"budget\": "<<r.budget<<", \"policy\": \""<<esc(r.policy)<<"\", \"mean_support_score\": "<<r.support/n<<", \"stale_invalidation_miss_rate\": "<<r.stale_miss/n<<", \"contamination_read_rate\": "<<r.contam/n<<", \"mean_cost\": "<<r.cost/n<<", \"mean_utility\": "<<r.utility/n<<", \"catastrophic_evidence_failure_rate\": "<<r.cat/n<<"}";} f<<"\n  ]\n}\n"; std::cerr<<"wrote "<<out<<" rows="<<rows.size()<<"\n"; return 0;}
